<?php
namespace App\Support;
use App\Models\{User,Apprentice,TutorGroup,TrainingSession,AttendanceMark,TimetableChangeBatch as Batch};
use Illuminate\Support\Facades\{DB,Crypt};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
use Carbon\Carbon;
class TimetableChanges {
 public const MODES=['move'=>'Move future session dates','roster'=>'Reconcile future saved rosters','cancel'=>'Cancel future unmarked sessions'];
 private static function fail(string $m='The source, timetable or access changed. Prepare a new exact preview.'):never {throw ValidationException::withMessages(['timetable'=>$m]);}
 public static function time(string $v):bool {return (bool)preg_match('/^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/D',$v);}
 public static function starts(TrainingSession $s):Carbon {if(!self::time($s->start_time)||!self::time($s->end_time)||$s->end_time<=$s->start_time){self::fail('Saved session timing needs a source check.');}return Carbon::parse($s->session_date->toDateString().' '.$s->start_time,config('app.timezone'));}
 public static function conflicts(array $candidate,array $ignore=[]):array {
  $hits=[];foreach(TrainingSession::with('group')->whereDate('session_date',$candidate['date'])->where('state','!=','Cancelled')->whereNotIn('id',$ignore)->orderBy('id')->get()as$other){$roster=RegisterFollowup::roster($other);$sameGroup=$other->tutor_group_id===$candidate['group_id'];$sameTutor=$candidate['tutor_id']&&$other->group?->tutor_id===$candidate['tutor_id'];$shared=(bool)array_intersect($candidate['members'],$roster['ids']);$unknown=!$roster['shape']||!self::time($other->start_time)||!self::time($other->end_time);if(!$sameGroup&&!$sameTutor&&!$shared&&!$unknown){continue;}if($unknown||($other->start_time<$candidate['end']&&$other->end_time>$candidate['start'])){$hits[]=['id'=>$other->id,'hash'=>ReviewedImports::hash($other->getAttributes()),'reason'=>$unknown?'Other timetable source needs checking':($sameGroup?'Group overlap':($sameTutor?'Group tutor overlap':'Saved learner overlap'))];}}
  return $hits;
 }
 private static function capture(string $mode,int $group,array $ids,int $shift,bool $lock=false):array {
  if(!isset(self::MODES[$mode])||!count($ids)||count($ids)>50||count(array_unique($ids))!==count($ids)||($mode==='move'&&(!$shift||abs($shift)>365))||($mode!=='move'&&$shift!==0)){self::fail('Choose1–50 distinct sessions and a valid operation; date moves need non-zero days within365.');}sort($ids,SORT_NUMERIC);
  if ($lock && $mode !== 'cancel') TeachingAllocationChecks::lock();
  $g=TutorGroup::whereKey($group)->when($lock,fn($q)=>$q->lockForUpdate())->firstOrFail();$teacher=$g->tutor_id?User::whereKey($g->tutor_id)->when($lock,fn($q)=>$q->lockForUpdate())->first():null;
  if($mode!=='cancel'&&(!$g->active||!$teacher?->active||$teacher->role!=='tutor')){self::fail('Date/roster changes need an active group and active primary group tutor.');}
  $sessions=TrainingSession::whereIn('id',$ids)->orderBy('id')->when($lock,fn($q)=>$q->lockForUpdate())->get();if($sessions->count()!==count($ids)){self::fail();}$current=Apprentice::where('tutor_group_id',$g->id)->orderBy('id')->when($lock,fn($q)=>$q->lockForUpdate())->get();$currentIds=$current->pluck('id')->all();if($mode==='roster'&&!$currentIds){self::fail('Current group has no members; check source rather than saving an empty roster.');}$rows=[];$changed=0;
  foreach($sessions as$s){if($s->tutor_group_id!==$g->id||$s->state!=='Planned'||!self::starts($s)->gt(now())||AttendanceMark::where('training_session_id',$s->id)->exists()||filled($s->delivered_learning)){self::fail('Only future, unstarted, unmarked Planned sessions with no delivered-learning record can change here.');}$r=RegisterFollowup::roster($s);if(!$r['shape']||$r['duplicates']){self::fail('Malformed/duplicate saved roster needs a manager source check; this tool is not raw-data repair.');}$old=$r['ids'];sort($old);$members=$mode==='roster'?$currentIds:$old;$date=$mode==='move'?$s->session_date->copy()->addDays($shift)->toDateString():$s->session_date->toDateString();if(!Carbon::parse($date.' '.$s->start_time,config('app.timezone'))->gt(now())){self::fail('Proposed session must still start in the future.');}$candidate=['group_id'=>$g->id,'tutor_id'=>$g->tutor_id,'date'=>$date,'start'=>$s->start_time,'end'=>$s->end_time,'members'=>$members];if($mode!=='cancel'&&self::conflicts($candidate,$ids)){self::fail('Proposed date/roster conflicts with a group, tutor, learner or uncertain timetable source. No change saved.');}
   if ($mode !== 'cancel') {
       TeachingAllocationChecks::checkDates($g, $members, [$date], 'timetable', $ids, $lock);
   }
   $people=Apprentice::whereIn('id',array_values(array_unique([...$old,...$members])))->orderBy('id')->when($lock,fn($q)=>$q->lockForUpdate())->get();$names=[];$seals=[];$dateWarnings=[];foreach($people as$a){$names[$a->id]=['id'=>$a->id,'reference'=>$a->reference,'name'=>trim($a->first_name.' '.$a->last_name),'start_date'=>$a->start_date?->toDateString(),'planned_end_date'=>$a->planned_end_date?->toDateString()];if(in_array($a->id,array_diff($members,$old),true)&&(!$a->start_date||$a->start_date->toDateString()>$date||($a->planned_end_date&&$a->planned_end_date->toDateString()<$date))){$dateWarnings[]=$a->id;}$seals[$a->id]=ReviewedImports::hash($a->getAttributes());}$different=$mode!=='roster'||$old!==$members;if($different){$changed++;}$rows[]=['id'=>$s->id,'name'=>$s->name,'version'=>$s->version,'before_hash'=>ReviewedImports::hash($s->getAttributes()),'old_date'=>$s->session_date->toDateString(),'date'=>$date,'start'=>$s->start_time,'end'=>$s->end_time,'old_members'=>$old,'members'=>$members,'added'=>array_values(array_diff($members,$old)),'removed'=>array_values(array_diff($old,$members)),'people'=>$names,'date_warnings'=>$dateWarnings,'profile_seals'=>$seals,'changed'=>$different,'candidate'=>$candidate];
  }
  if(!$changed){self::fail('Selected saved rosters already match current group membership.');}if($mode!=='cancel'){for($i=0;$i<count($rows);$i++){for($j=$i+1;$j<count($rows);$j++){if($rows[$i]['date']===$rows[$j]['date']&&$rows[$i]['start']<$rows[$j]['end']&&$rows[$i]['end']>$rows[$j]['start']){self::fail('Selected sessions would overlap each other.');}}}}
  return ['mode'=>$mode,'group_id'=>$g->id,'group_name'=>$g->name,'group_hash'=>ReviewedImports::hash($g->getAttributes()),'teacher'=>$teacher?StaffHandover::staffSeal($teacher):null,'shift_days'=>$shift,'current_group_seals'=>$mode==='roster'?$current->map(fn($a)=>['id'=>$a->id,'hash'=>ReviewedImports::hash($a->getAttributes())])->all():[],'rows'=>$rows,'changed'=>$changed,'mixed_main_tutors'=>$current->contains(fn($a)=>$a->tutor_id!==$g->tutor_id),'warning'=>'No programme-status filter inferred. Roster changes alter who appears in future registers, not current group/profile assignments or recorded attendance. Existing group/main-tutor scope rules remain.' ];
 }
 private static function actor(User $u,int $auth):User {$u=User::whereKey($u->id)->lockForUpdate()->firstOrFail();abort_unless(LearningAccess::manager($u)&&$u->auth_version===$auth,403);return $u;}
 private static function event(Batch $b,User $u,string $event,array $payload=[]):void {DB::table('timetable_change_events')->insert(['batch_id'=>$b->id,'actor_id'=>$u->id,'event'=>$event,'record_version'=>$b->version,'payload'=>Crypt::encryptString(json_encode($payload,JSON_THROW_ON_ERROR)),'created_at'=>now()]);}
 public static function intact(Batch $b):bool {try{$s=$b->source;return $s&&ReviewedImports::hash($s)===$b->source_hash&&$s['creator']['id']===$b->created_by&&$s['request']===$b->request_token&&$s['mode']===$b->mode&&$s['group_id']===$b->tutor_group_id&&$s['expires_at']===$b->expires_at->toIso8601String();}catch(\Throwable){return false;}}
 public static function fresh(Batch $b,bool $lock=false):bool {try{if(!self::intact($b)||$b->state!=='Pending'||now()->greaterThanOrEqualTo($b->expires_at)){return false;}$s=$b->source;$u=User::find($b->created_by);if(!$u||!LearningAccess::manager($u)||$u->auth_version!==$s['creator']['auth_version']){return false;}$captured=self::capture($b->mode,$b->tutor_group_id,array_column($s['rows'],'id'),$s['shift_days'],$lock);unset($s['creator'],$s['reason'],$s['request'],$s['expires_at']);return ReviewedImports::hash($s)===ReviewedImports::hash($captured);}catch(\Throwable){return false;}}
 public static function prepare(User $actor,int $auth,string $request,string $mode,int $group,array $ids,int $shift,string $reason):Batch {
  if(!Str::isUuid($request)||trim($reason)===''||mb_strlen($reason)>2000){self::fail('Use a valid request and safe source/reason reference.');}return DB::transaction(function()use($actor,$auth,$request,$mode,$group,$ids,$shift,$reason):Batch {$m=self::actor($actor,$auth);$old=Batch::where('request_token',$request)->lockForUpdate()->first();sort($ids);if($old){if(self::intact($old)&&$old->created_by===$m->id&&$old->source['creator']['auth_version']===$m->auth_version&&$old->mode===$mode&&$old->tutor_group_id===$group&&$old->source['shift_days']===$shift&&array_column($old->source['rows'],'id')===$ids&&$old->source['reason']===$reason){return $old;}self::fail('Request already used with different source. Reload the form.');}$source=self::capture($mode,$group,$ids,$shift,true);$expires=now()->addDay()->setMicrosecond(0);$source+=['creator'=>['id'=>$m->id,'auth_version'=>$m->auth_version],'request'=>$request,'reason'=>$reason,'expires_at'=>$expires->toIso8601String()];$b=new Batch(['request_token'=>$request,'created_by'=>$m->id,'tutor_group_id'=>$group,'mode'=>$mode,'state'=>'Pending','version'=>1,'source'=>$source,'source_hash'=>ReviewedImports::hash($source),'expires_at'=>$expires]);$b->id=(string)Str::uuid();$b->save();self::event($b,$m,'preview_prepared',['source_hash'=>$b->source_hash]);return $b;},3);
 }
 public static function applied(Batch $b):bool {try{$p=$b->receipt;return self::intact($b)&&$b->state==='Applied'&&$b->reviewed_by&&$b->reviewed_by!==$b->created_by&&$b->reviewed_at&&$p&&$p['source_hash']===$b->source_hash&&$p['version']===$b->version&&$p['by']===$b->reviewed_by&&$p['at']===$b->reviewed_at->toIso8601String()&&count($p['after'])===count($b->source['rows']);}catch(\Throwable){return false;}}
 public static function decide(User $actor,int $auth,Batch $record,int $version,string $decision,string $note):void {
  DB::transaction(function()use($actor,$auth,$record,$version,$decision,$note):void {User::whereIn('id',[$actor->id,$record->created_by])->orderBy('id')->lockForUpdate()->get();$m=self::actor($actor,$auth);$b=Batch::whereKey($record->id)->lockForUpdate()->firstOrFail();if(!self::intact($b)||$b->state!=='Pending'||$b->version!==$version||!in_array($decision,['apply','reject','withdraw'],true)){self::fail('Use the current intact pending preview.');}if($decision!=='withdraw'&&$b->created_by===$m->id){self::fail('A different administrator/CEO must apply or reject.');}$after=[];
   if($decision==='apply'){if(!self::fresh($b,true)){self::fail();}foreach($b->source['rows']as$row){$s=TrainingSession::findOrFail($row['id']);if($row['changed']){$before=$s->only(['session_date','state','members','version']);if($b->mode==='move'){$s->session_date=$row['date'];}elseif($b->mode==='roster'){$s->members=$row['members'];}else{$s->state='Cancelled';$s->cancellation_reason='Checked timetable batch '.$b->id;}$h=$s->history??[];$h[]=['event'=>'checked_'.$b->mode,'batch_id'=>$b->id,'by'=>$m->id,'at'=>now()->toIso8601String(),'before'=>$before];$s->history=$h;$s->version++;$s->save();foreach(Apprentice::whereIn('id',array_values(array_unique([...$row['old_members'],...$row['members']])))->pluck('id')as$id){DB::table('learning_events')->insert(['user_id'=>$m->id,'apprentice_id'=>$id,'kind'=>'session','record_id'=>$s->id,'event'=>'timetable_'.$b->mode,'created_at'=>now()]);}}$after[]=['id'=>$s->id,'version'=>$s->version,'hash'=>ReviewedImports::hash($s->getAttributes())];}}
   $b->state=['apply'=>'Applied','reject'=>'Rejected','withdraw'=>'Withdrawn'][$decision];$b->version++;$b->reviewed_by=$m->id;$b->reviewed_at=now()->setMicrosecond(0);$b->review_note=$note;$b->receipt=$decision==='apply'?['source_hash'=>$b->source_hash,'version'=>$b->version,'by'=>$m->id,'at'=>$b->reviewed_at->toIso8601String(),'after'=>$after]:null;$b->save();self::event($b,$m,'preview_'.$decision,['after'=>$after,'note'=>$note]);
  },3);
 }
}
